param([string]$SelectionPath='',[switch]$RequireIntegrated=$true,[string]$OutputRoot='')
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$repo=$PSScriptRoot;while(-not [IO.File]::Exists((Join-Path $repo 'bootstrap/tools/verification.ps1'))){$parent=Split-Path $repo -Parent;if(-not $parent -or $parent -eq $repo){throw 'Repository root not found'};$repo=$parent}
. (Join-Path $repo 'bootstrap/tools/verification.ps1')
if(-not $OutputRoot){$OutputRoot=Join-Path $repo 'bootstrap/out/semantic-whole'}
$reportDirectory=Join-Path $OutputRoot ([Guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($reportDirectory)
$checks=New-Object 'Collections.Generic.List[object]';$commands=New-Object 'Collections.Generic.List[object]';$selection=$null;$failure=$null;$success=$false;$inputs=@();$run=$null;$stage1=$null
function Invoke-Child([string]$Script,[hashtable]$Parameters,[string]$Prefix='Evidence: '){
 $output=@(& $Script @Parameters);$lines=@($output|Where-Object {$_ -is [string] -and $_.StartsWith($Prefix)});if($lines.Count -ne 1){throw "Expected exactly one $Prefix line from $Script"};$path=[IO.Path]::GetFullPath($lines[0].Substring($Prefix.Length));$commands.Add([pscustomobject]@{script=(Get-ArtifactIdentity $Script);parameters=$Parameters;output=$output;result=$path});return $path
}
function Check-Report([string]$Name,[string]$Path){$actual=[IO.File]::ReadAllText($Path)|ConvertFrom-Json;if(-not $actual.success){throw "$Name failed: $Path"};$checks.Add([pscustomobject]@{assertion=$Name;passed=$true;report=(Get-ArtifactIdentity $Path)});return $actual}
try{
 if(-not $SelectionPath){$SelectionPath=Join-Path $repo 'bootstrap/out/v2/current.json'};$selection=Get-VerifiedBootstrapSelection $SelectionPath
 if(-not $RequireIntegrated){throw 'Whole semantic gate requires the actual production compiler manifest and real UBECore Reference'}
 $native=Split-Path $PSScriptRoot -Parent;$oracle=Join-Path $native 'complete/complete.json';$commonSource=Join-Path $native 'complete/sources';$inputs+=@(Get-ChildItem -LiteralPath $PSScriptRoot -File|ForEach-Object {Get-ArtifactIdentity $_.FullName});$inputs+=@($SelectionPath,$oracle,(Join-Path $native 'complete-project-facts.ps1'),(Join-Path $native 'targeted-calls.ps1'),(Join-Path $native 'check-complete-projects.ps1'),(Join-Path $repo 'compiler/UBE_Compiler_v3/tests/semantic/cases.json'),(Join-Path $repo 'compiler/UBE_Compiler_v3/tests/semantic/definition.json')|ForEach-Object {Get-ArtifactIdentity $_})
 foreach($directory in @('complete','four-context')){$inputs+=@(Get-ChildItem -LiteralPath (Join-Path $native $directory) -Recurse -File|ForEach-Object {Get-ArtifactIdentity $_.FullName})}
 $build=Invoke-Child (Join-Path $PSScriptRoot 'build.ps1') @{SelectionPath=$SelectionPath;OutputRoot=$reportDirectory};$built=Check-Report 'Stage2 complete ScalarApp declarations/signatures/bindings/types/constants/conversions/value graph and basic ownership' $build;$run=Split-Path $build -Parent;$inputs+=@($built.inputs)
 $stage1=Invoke-Child (Join-Path $PSScriptRoot 'second-stage.ps1') @{RunPath=$run;SelectionPath=$SelectionPath};$other=Check-Report 'Stage1 same complete independent ScalarApp assertions; exact raw LLVM stage identity' $stage1
 $executables=@{};$single=@{};$projects=@{};$overlap=@{}
 foreach($stage in @('stage1','stage2')){
  $args=@{RunPath=$run};if($stage -eq 'stage1'){$args.Stage1ReportPath=$stage1}
  $exe=Invoke-Child (Join-Path $PSScriptRoot 'targeted-link.ps1') $args 'Targeted executable: ';$executables[$stage]=$exe
  $single[$stage]=Invoke-Child (Join-Path $PSScriptRoot 'targeted-check.ps1') @{Executable=$exe};$actual=Check-Report "$stage all single-source authored semantic outcomes/spans/facts and corruption controls" $single[$stage];if($actual.passed -ne 186 -or $actual.failed -ne 0 -or $actual.controls.Count -ne 5){throw 'Complete single-source semantic fixture cohort and five controls required'};foreach($record in $actual.records){if($null -ne $record.facts -and @($record.facts.unsupported).Count -ne 0){throw ('Uncompared authored fact: '+$record.id)}}
  $projects[$stage]=Invoke-Child (Join-Path $PSScriptRoot 'targeted-project-check.ps1') @{Executable=$exe};$actual=Check-Report "$stage actual multi-source/project/reference cases at jobs1/2/4" $projects[$stage];if($actual.passed -ne 48 -or $actual.failed -ne 0){throw 'Complete project semantic fixture cohort required'};foreach($record in $actual.records){if($null -ne $record.facts -and @($record.facts.unsupported).Count -ne 0){throw ('Uncompared authored project fact: '+$record.id)}}
  $overlap[$stage]=Invoke-Child (Join-Path $PSScriptRoot 'overlap-check.ps1') $args;$null=Check-Report "$stage actual static UBE workers/captures overlap at jobs1/2/4 and capture corruption control" $overlap[$stage]
  $cohort=Invoke-Child (Join-Path $PSScriptRoot 'run-resource-cohort.ps1') $args 'Cohort: ';$actual=Check-Report "$stage full coordinator allocation/root/cancellation/drain/budget/cost/ordering cohort" $cohort;if($actual.cases.Count -ne 17){throw 'All 17 resource/control children required'}
 }
 foreach($family in @('single','projects')){$pair=if($family -eq 'single'){$single}else{$projects};$path=Invoke-Child (Join-Path $PSScriptRoot 'compare-stage-observations.ps1') @{FirstReport=$pair.stage1;SecondReport=$pair.stage2};$null=Check-Report "Complete $family observation bytes identical across source-built stages" $path}
 $path=Invoke-Child (Join-Path $PSScriptRoot 'compare-overlap-stages.ps1') @{FirstReport=$overlap.stage1;SecondReport=$overlap.stage2};$null=Check-Report 'Complete overlap scalar streams and preset capture/worker bounds match across stages' $path
 $completeBaselines=@{};foreach($jobs in @(1,2,4)){$observations=Join-Path $reportDirectory ('complete-jobs'+$jobs);[void][IO.Directory]::CreateDirectory($observations);$fixtures=@{'argument-modes-and-control'='ArgumentModes.UBE';'explicit-native-library'='NativeConsumer.UBE';'duplicate-folded-name-preserves-result'='DuplicateNames.UBE'};foreach($stage in @('stage1','stage2')){foreach($id in $fixtures.Keys){$manifest=Join-Path (Join-Path $commonSource $id) $fixtures[$id];$record=Invoke-BoundedProcess $executables[$stage] @('--project',$manifest,[string]$jobs) $repo 60;$commands.Add($record);if($record.timedOut -or $record.exit -ne 0 -or $record.stderr -cne ''){throw 'Complete representative project transport failed'};$key=$stage+'/'+$id;if($completeBaselines.ContainsKey($key)){if($completeBaselines[$key] -cne $record.stdout){throw 'Complete representative scalar stream differs across jobs'}}else{$completeBaselines[$key]=$record.stdout};[IO.File]::WriteAllText((Join-Path $observations ($stage+'-'+$id+'.json')),$record.stdout,(New-Object Text.UTF8Encoding($false)))}};$path=Invoke-Child (Join-Path $native 'check-complete-projects.ps1') @{ObservationDirectory=$observations;OutputDirectory=(Join-Path $observations 'comparison')};$null=Check-Report "Exact Calls/Native declarations/bindings/expressions/calls/control/nominal types and duplicate diagnostic, both stages jobs$jobs" $path}
 $sharing=Invoke-Child (Join-Path $native 'four-context/check.ps1') @{RunPath=$run;NativeFixtureDirectory=$PSScriptRoot};$null=Check-Report 'Four simultaneous complete checker contexts share immutable input; private outputs/budgets/cancel/Err, captured owners and GC lifetime' $sharing
 foreach($identity in $inputs){if((Get-ArtifactIdentity $identity.path).sha256 -cne $identity.sha256){throw ('Gate input changed: '+$identity.path)}};$null=Get-VerifiedBootstrapSelection $SelectionPath;$checks.Add([pscustomobject]@{assertion='Accepted bootstrap selection and every recorded producer/fixture input remain unchanged';passed=$true});$success=$true
}catch{$failure=$_.Exception.Message}
finally{$path=Join-Path $reportDirectory 'report.json';[pscustomobject]@{success=$success;qualified=$success;failure=$failure;acceptedSelection=$selection;checks=$checks.ToArray();inputs=$inputs;wholeRun=$run;stage1Report=$stage1;commands=$commands.ToArray();limits='Bounded supported semantic contract only. Exact independent representative streams plus all 202 semantic source/project cases; three retained frontend-only cases belong to existing frontend gates. Native resource cohorts exhaust the finite baseline allocation sites, real root boundaries, specified budget families and measured cost sizes; no claim over every possible program or arbitrary system-failure interleaving.'}|ConvertTo-Json -Depth 32|Set-Content -LiteralPath $path -Encoding UTF8;Write-Output "Evidence: $path"}
if(-not $success){throw $failure}
